script:
$ErrorActionPreference = 'Stop'
function Read-Git([string[]]$Arguments) {
    $output = & git @Arguments 2>&1
    if ($LASTEXITCODE -ne 0) { throw "Read-only Git check failed: $($Arguments -join ' '): $($output -join [Environment]::NewLine)" }
    return ($output | Out-String).Trim()
}
$mutex = [Threading.Mutex]::new($false, 'Local\AppScalingStrategies_KanbanPublisher_v1')
$held = $false
try {
    $held = $mutex.WaitOne([TimeSpan]::FromSeconds(180))
    if (-not $held) { throw 'Publisher mutex timeout; no lock removal or serialization bypass.' }
    $branch = Read-Git @('branch', '--show-current')
    $head = Read-Git @('rev-parse', 'HEAD')
    $main = Read-Git @('rev-parse', 'refs/heads/main')
    $tracking = Read-Git @('rev-parse', 'refs/remotes/origin/main')
    $remoteLine = Read-Git @('ls-remote', 'origin', 'refs/heads/main')
    if ($remoteLine -notmatch '^([a-f0-9]{40})\s+refs/heads/main$') { throw 'Remote main must have one exact reference.' }
    $remote = $Matches[1]
    [ordered]@{branch=$branch;head=$head;main=$main;trackingMain=$tracking;remoteMain=$remote;underPublisherMutex=$true} | ConvertTo-Json -Compress | Write-Output
    if ($branch -ne 'main' -or $head -ne $main -or $head -ne $tracking -or $head -ne $remote) {
        throw 'HEAD_MAIN_MISMATCH: stop/report; no staging or publication may carry an unpublished foreign commit.'
    }
    & .git\kanban-orchestrator\publish.ps1 -CardId C048 -WorkerId worker-C048 -Paths @('capability\C048') -Message '[C048][D] Gate local DATA/EVENT admission with retained RED and actual signed-browser proof'
} finally {
    if ($held) { $mutex.ReleaseMutex() }
    $mutex.Dispose()
}
